    const present = new Set(prerequisites.map(({ issue }) => issueReferenceKey(issue.ref)));
    const mismatches = lines
        .filter(line => !present.has(issueReferenceKey(line.ref)))
        .map(line => ({ ref: line.ref, reason: line.reason }));
