        let token = '';
        try {
            const result = await runProcess('gh', arguments_, { stdin: 'ignore', timeoutMilliseconds: this.ghTimeoutMilliseconds, signal: this.signal });
            token = result.exitCode === 0 && !result.isTimedOut ? pythonStrip(result.stdout) : '';
        }
